reminder_source='package uk.co.littledays;\n\nimport android.Manifest;\nimport android.app.*;\nimport android.content.*;\nimport android.content.pm.PackageManager;\nimport android.os.*;\nimport android.util.AtomicFile;\nimport org.json.*;\nimport java.io.*;\nimport java.time.*;\nimport java.time.temporal.ChronoUnit;\nimport java.util.*;\n\npublic class TaskReminders extends BroadcastReceiver {\n static final String CHECK="uk.co.littledays.CHECK_TASKS",CHANNEL="unfinished_tasks";\n @Override public void onReceive(Context context,Intent intent){if(CHECK.equals(intent.getAction()))deliver(context);sync(context);}\n static JSONObject read(Context context){try(InputStream in=new AtomicFile(new File(context.getFilesDir(),"data.json")).openRead()){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)bytes.write(buffer,0,n);return new JSONObject(bytes.toString("UTF-8"));}catch(Exception e){return new JSONObject();}}\n static LocalDate anchor(JSONObject task,LocalDate fallback){try{return LocalDate.parse(task.optString("createdOn",fallback.toString()));}catch(Exception e){return fallback;}}\n static boolean due(JSONObject task,LocalDate day){long elapsed=ChronoUnit.DAYS.between(anchor(task,day),day);return elapsed>=0&&elapsed%Math.max(1,task.optInt("repeat",1))==0;}\n static boolean done(JSONObject task,JSONObject data,LocalDate day){return task.optBoolean("done")&&(!data.optBoolean("resetDaily",true)||day.toString().equals(task.optString("completedOn")));}\n static long at(JSONObject task,LocalDate day){int hour=Math.max(0,Math.min(23,task.optInt("reminderHour",18))),minute=Math.max(0,Math.min(59,task.optInt("reminderMinute",0)));return day.atTime(hour,minute).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();}\n static int notificationId(String id){return id.hashCode()&0x7fffffff;}\n static NotificationManager manager(Context context){NotificationManager manager=(NotificationManager)context.getSystemService(Context.NOTIFICATION_SERVICE);if(manager!=null){NotificationChannel channel=new NotificationChannel(CHANNEL,"Unfinished task reminders",NotificationManager.IMPORTANCE_DEFAULT);channel.setDescription("A reminder for an unchecked task at its chosen time on scheduled days");channel.setLockscreenVisibility(Notification.VISIBILITY_PRIVATE);manager.createNotificationChannel(channel);}return manager;}\n static PendingIntent alarmIntent(Context c){return PendingIntent.getBroadcast(c,410,new Intent(c,TaskReminders.class).setAction(CHECK),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}\n static boolean allowed(Context context,NotificationManager manager){return manager!=null&&context.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED&&manager.areNotificationsEnabled();}\n public static synchronized void sync(Context context){try{\n  NotificationManager notifications=manager(context);AlarmManager alarms=(AlarmManager)context.getSystemService(Context.ALARM_SERVICE);if(alarms==null)return;PendingIntent alarm=alarmIntent(context);JSONObject data=read(context);JSONArray tasks=data.optJSONArray("tasks");SharedPreferences history=context.getSharedPreferences("task_reminder_delivery",Context.MODE_PRIVATE);Set<String> previously=new HashSet<>(history.getStringSet("active",Collections.emptySet()));HashSet<String> active=new HashSet<>();LocalDate today=LocalDate.now();long now=System.currentTimeMillis(),earliest=Long.MAX_VALUE;boolean canNotify=allowed(context,notifications);\n  if(tasks!=null)for(int i=0;i<tasks.length();i++){JSONObject task=tasks.optJSONObject(i);if(task==null||!task.optBoolean("reminder"))continue;String id=task.optString("id");if(id.isEmpty())continue;if(due(task,today)&&!done(task,data,today)&&at(task,today)>=task.optLong("reminderEnabledAt",0))active.add(id);if(!canNotify)continue;\n   int interval=Math.max(1,task.optInt("repeat",1));LocalDate created=anchor(task,today);long elapsed=ChronoUnit.DAYS.between(created,today);LocalDate day=elapsed<0?created:today.plusDays(Math.floorMod(-elapsed,(long)interval));\n   for(int pass=0;pass<3;pass++,day=day.plusDays(interval)){if(done(task,data,day))continue;if(day.toString().equals(history.getString("sent:"+id,"")))continue;long trigger=at(task,day);if(trigger<task.optLong("reminderEnabledAt",0))continue;earliest=Math.min(earliest,Math.max(trigger,now+3000));break;}\n  }\n  if(notifications!=null)for(String id:previously)if(!active.contains(id))notifications.cancel(notificationId(id));history.edit().putStringSet("active",active).apply();alarms.cancel(alarm);if(!canNotify||earliest==Long.MAX_VALUE)return;\n  if(alarms.canScheduleExactAlarms()){try{alarms.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,earliest,alarm);return;}catch(SecurityException ignored){}}\n  alarms.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,earliest,alarm);\n }catch(Exception e){android.util.Log.w("ADayToKeep","Reminder scheduling deferred",e);}}\n static synchronized void deliver(Context context){try{NotificationManager notifications=manager(context);if(!allowed(context,notifications))return;JSONObject data=read(context);JSONArray tasks=data.optJSONArray("tasks");if(tasks==null)return;LocalDate today=LocalDate.now();long now=System.currentTimeMillis();SharedPreferences history=context.getSharedPreferences("task_reminder_delivery",Context.MODE_PRIVATE);\n  for(int i=0;i<tasks.length();i++){JSONObject task=tasks.optJSONObject(i);if(task==null||!task.optBoolean("reminder")||!due(task,today)||done(task,data,today))continue;String id=task.optString("id");long target=at(task,today);if(id.isEmpty()||target>now||target<task.optLong("reminderEnabledAt",0)||today.toString().equals(history.getString("sent:"+id,"")))continue;\n   Intent open=new Intent(context,MainActivity.class).putExtra("fromWidget",true).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent tap=PendingIntent.getActivity(context,notificationId(id),open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification publicVersion=new Notification.Builder(context,CHANNEL).setSmallIcon(R.drawable.ic_task_reminder).setContentTitle("A Day To Keep").setContentText("A task reminder").build();Notification notification=new Notification.Builder(context,CHANNEL).setSmallIcon(R.drawable.ic_task_reminder).setContentTitle("A little reminder").setContentText(task.optString("text","An unfinished task")).setStyle(new Notification.BigTextStyle().bigText(task.optString("text"))).setContentIntent(tap).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE).setPublicVersion(publicVersion).build();notifications.notify(notificationId(id),notification);history.edit().putString("sent:"+id,today.toString()).apply();\n  }\n }catch(Exception e){android.util.Log.w("ADayToKeep","Could not show reminder",e);}}\n}\n'
Path('app/src/main/java/uk/co/littledays/TaskReminders.java').write_text(reminder_source,encoding='utf-8')

